cd /home/sfmqrb/git/rishe/data/verification/sources/refs && python3 - <<'EOF'
import re
lines=open('incoming/ARY/ARY_pages.txt',encoding='utf-8',errors='replace').read().split('\n')
def pg(n):
    for i in range(n,0,-1):
        m=re.search(r'\[pdf page (\d+)\]',lines[i])
        if m: return m.group(1)
    return '?'
for n in [576,6414]:
    print('--- line',n,'pdf page',pg(n))
    for l in lines[n-12:n+12]:
        if l.strip(): print('   ',l.strip()[:200])
EOF

